// Build greeting text based on pending attention items
const attentionData = $input.first().json;
const items = attentionData.items || [];
const pendingCount = items.filter(i => !i.resolvedAt).length;

let greeting;
if (pendingCount > 0) {
  greeting = `Hey! I've got ${pendingCount} thing${pendingCount > 1 ? 's' : ''} waiting for you. Want to handle those first, or start something new?`;
} else {
  greeting = "Hey! What would you like to work on?";
}

const webhookData = $('Telnyx Voice Webhook').first().json;
const callControlId = webhookData.data.payload.call_control_id;

const state = {
  history: [],
  lastIntent: null,
  sessionContext: {},
  turnCount: 0,
  consecutiveTimeouts: 0,
  pendingAttentionCount: pendingCount
};

return {
  json: {
    greeting,
    callControlId,
    clientState: Buffer.from(JSON.stringify(state)).toString('base64'),
    pendingCount
  }
};

// Extract state and transcript from gather.ended event
const webhookData = $('Telnyx Voice Webhook').first().json;
const payload = webhookData.data.payload;

let state;
try {
  const decoded = Buffer.from(payload.client_state || '', 'base64').toString('utf-8');
  state = JSON.parse(decoded);
} catch (e) {
  state = { history: [], lastIntent: null, sessionContext: {}, turnCount: 0, consecutiveTimeouts: 0 };
}

const transcript = payload.speech?.transcript || '';
const speechConfidence = payload.speech?.confidence || 0;
const timedOut = !transcript || transcript.trim() === '';

if (!timedOut) {
  state.history.push({ role: 'user', content: transcript });
  state.consecutiveTimeouts = 0;
}

if (state.history.length > 10) {
  state.history = state.history.slice(-10);
}

state.turnCount++;

return {
  json: {
    callControlId: payload.call_control_id,
    transcript,
    speechConfidence,
    timedOut,
    state,
    turnCount: state.turnCount
  }
};

// Handle timeout
const state = { ...$json.state };
const timeoutCount = (state.consecutiveTimeouts || 0) + 1;
state.consecutiveTimeouts = timeoutCount;

let responseText;
let shouldHangup = false;

if (timeoutCount >= 2) {
  responseText = "I'll let you go for now. Call back when you're ready!";
  shouldHangup = true;
} else {
  responseText = "Still there? I didn't hear anything.";
}

const audioTimestamp = Date.now();

return {
  json: {
    callControlId: $json.callControlId,
    responseText,
    shouldHangup,
    state,
    clientState: Buffer.from(JSON.stringify(state)).toString('base64'),
    audioTimestamp,
    intent: 'timeout'
  }
};

// Parse Claude's intent classification response
const claudeResponse = $input.first().json;
const prevData = $('Build Intent Prompt').first().json;

let intentData;
try {
  const text = claudeResponse.content[0].text;
  let jsonStr = text;
  const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/) || text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1] || jsonMatch[0];
  }
  intentData = JSON.parse(jsonStr.trim());
} catch (e) {
  intentData = { intent: 'unknown', sessionName: null, message: null, confidence: 0 };
}

return {
  json: {
    intent: intentData.intent || 'unknown',
    sessionName: intentData.sessionName || null,
    message: intentData.message || prevData.transcript,
    confidence: intentData.confidence || 0,
    callControlId: prevData.callControlId,
    transcript: prevData.transcript,
    state: prevData.state
  }
};

// Build response text based on intent and Pi API response
const intentData = $('Parse Intent').first().json;
const piResponse = $input.first().json;
const intent = intentData.intent;

let responseText = '';
let updatedSessionContext = { ...intentData.state.sessionContext };

switch (intent) {
  case 'create_session': {
    if (piResponse.session) {
      updatedSessionContext = { sessionId: piResponse.session.id, sessionName: piResponse.session.name };
      responseText = intentData.message
        ? `${piResponse.session.name} is running and I've sent over your instructions. Claude's on it.`
        : `Got it, ${piResponse.session.name} is up and running. What should Claude work on first?`;
    } else {
      const errorMsg = piResponse.error || piResponse.message || '';
      responseText = errorMsg.toLowerCase().includes('exists')
        ? `There's already a session called ${intentData.sessionName}. Want me to use that one?`
        : `Sorry, I couldn't create that session. ${errorMsg || 'Something went wrong.'}`;
    }
    break;
  }
  case 'list_sessions': {
    const sessions = piResponse.sessions || piResponse || [];
    const sessionList = Array.isArray(sessions) ? sessions : [];
    if (sessionList.length === 0) {
      responseText = "No sessions running right now. Want to start one?";
    } else {
      const statusMap = { running: 'actively working', idle: 'idle', error: 'has errors', waiting_input: 'waiting for input', preserved: 'preserved' };
      const descriptions = sessionList.map(s => `${s.name} is ${statusMap[s.status] || s.status}`).join('. ');
      responseText = `You've got ${sessionList.length} session${sessionList.length > 1 ? 's' : ''} running. ${descriptions}.`;
      if (sessionList.length === 1) updatedSessionContext = { sessionId: sessionList[0].id, sessionName: sessionList[0].name };
    }
    break;
  }
  case 'check_status': {
    const session = piResponse.session || piResponse;
    responseText = (session && session.name)
      ? `${session.name} is ${session.status}.${session.lastOutputPreview ? ' Latest: ' + session.lastOutputPreview.slice(0, 100) : ''}`
      : "I couldn't find that session. Want me to list what's running?";
    break;
  }
  case 'send_message':
    responseText = piResponse.success !== false
      ? `Done, I've passed that along to ${intentData.state.sessionContext.sessionName || 'the session'}.`
      : `Something went wrong sending that. ${piResponse.error || ''}`;
    break;
  case 'stop_session':
    responseText = piResponse.success !== false
      ? `Done, I've interrupted ${intentData.state.sessionContext.sessionName || 'the session'}.`
      : `I couldn't stop that session. ${piResponse.error || ''}`;
    break;
  case 'kill_session':
    responseText = piResponse.success !== false
      ? `Got it, ${intentData.state.sessionContext.sessionName || 'the session'} is shut down.`
      : `I couldn't kill that session. ${piResponse.error || ''}`;
    if (piResponse.success !== false) updatedSessionContext = {};
    break;
  case 'resume_session':
    responseText = piResponse.success !== false
      ? `${intentData.state.sessionContext.sessionName || 'The session'} is back up.`
      : `I couldn't resume that session. ${piResponse.error || ''}`;
    break;
  case 'get_errors': {
    const items = piResponse.items || piResponse || [];
    const itemList = Array.isArray(items) ? items : [];
    const unresolved = itemList.filter(i => !i.resolvedAt);
    responseText = unresolved.length === 0
      ? "No errors or pending items. Everything looks good!"
      : `You've got ${unresolved.length} item${unresolved.length > 1 ? 's' : ''} needing attention.`;
    break;
  }
  default:
    responseText = "Sorry, I didn't quite catch that. Could you say it again?";
}

const updatedState = { ...intentData.state, lastIntent: intent, sessionContext: updatedSessionContext, consecutiveTimeouts: 0 };
updatedState.history.push({ role: 'assistant', content: responseText });

return {
  json: {
    responseText,
    callControlId: intentData.callControlId,
    state: updatedState,
    clientState: Buffer.from(JSON.stringify(updatedState)).toString('base64'),
    intent,
    audioTimestamp: Date.now()
  }
};

// Build goodbye TTS text
const intentData = $('Parse Intent').first().json;
const state = intentData.state;
const hasActiveSessions = state.sessionContext && state.sessionContext.sessionId;

const responseText = hasActiveSessions
  ? "Alright, Claude's on it. I'll call if anything else comes up!"
  : "Talk soon!";

return {
  json: {
    responseText,
    callControlId: intentData.callControlId,
    state,
    clientState: Buffer.from(JSON.stringify(state)).toString('base64'),
    audioTimestamp: Date.now()
  }
};

// Log call on hangup
const webhookData = $('Telnyx Voice Webhook').first().json;
const payload = webhookData.data?.payload || {};

return {
  json: {
    direction: 'inbound',
    telnyx_call_control_id: payload.call_control_id || null,
    telnyx_call_leg_id: payload.call_leg_id || null,
    status: 'completed',
    caller_number: payload.from || null,
    started_at: new Date().toISOString(),
    metadata: { hangup_cause: payload.hangup_cause || 'normal' }
  }
};
